// Campaign Commands
data class CreateCampaignCommand(
    @Id var campaignId: UUID? = null,
    var name: String? = null,
    var startDate:  Date? = null,
    var endDate:  Date? = null,
         @AttributeOverrides(
      AttributeOverride( name = "amount", column = Column(name = "budget_amount")),
      AttributeOverride( name = "currency", column = Column(name = "budget_currency"))
    )
    var budget: Money? = null,
         @AttributeOverrides(
      AttributeOverride( name = "amount", column = Column(name = "actualCost_amount")),
      AttributeOverride( name = "currency", column = Column(name = "actualCost_currency"))
    )
    var actualCost: Money? = null,
         @AttributeOverrides(
      AttributeOverride( name = "amount", column = Column(name = "expectedRevenue_amount")),
      AttributeOverride( name = "currency", column = Column(name = "expectedRevenue_currency"))
    )
    var expectedRevenue: Money? = null,
    @Enumerated(EnumType.STRING) var status: CampaignStatus? = null,
    @Enumerated(EnumType.STRING) var type: CampaignType? = null
)

data class UpdateCampaignCommand(
    @Id var campaignId: UUID? = null,
    var name: String? = null,
    var startDate:  Date? = null,
    var endDate:  Date? = null,
         @AttributeOverrides(
      AttributeOverride( name = "amount", column = Column(name = "budget_amount")),
      AttributeOverride( name = "currency", column = Column(name = "budget_currency"))
    )
    var budget: Money? = null,
         @AttributeOverrides(
      AttributeOverride( name = "amount", column = Column(name = "actualCost_amount")),
      AttributeOverride( name = "currency", column = Column(name = "actualCost_currency"))
    )
    var actualCost: Money? = null,
         @AttributeOverrides(
      AttributeOverride( name = "amount", column = Column(name = "expectedRevenue_amount")),
      AttributeOverride( name = "currency", column = Column(name = "expectedRevenue_currency"))
    )
    var expectedRevenue: Money? = null,
    var organization: Organization? = null,
    var parentCampaign: Campaign? = null,
    var childCampaigns:  Set<Campaign>? = null,
    var members:  Set<CampaignMember>? = null,
    var opportunities:  Set<Opportunity>? = null,
    var accounts:  Set<Account>? = null,
    var leads:  Set<Lead>? = null,
    var contacts:  Set<Contact>? = null,
    var teams:  Set<Team>? = null,
    var activities:  Set<Activity>? = null,
    @Enumerated(EnumType.STRING) var status: CampaignStatus? = null,
    @Enumerated(EnumType.STRING) var type: CampaignType? = null
)

data class DeleteCampaignCommand(@Id  var campaignId: UUID? = null)

